<!doctype html><html><head><meta charset="utf-8"><title>Post job</title></head><body style="background:#f5f7fb;font:15px Inter,system-ui"><form method="post" action="{{$job->exists?route('employer.jobs.update',$job):route('employer.jobs.store')}}" style="max-width:800px;margin:30px auto;padding:28px;background:white">@csrf @if($job->exists)@method('PUT')@endif<h1>{{$job->exists?'Edit job':'Post a job'}}</h1>@foreach($errors->all() as $error)<p style="color:#b91c1c">{{$error}}</p>@endforeach@foreach(['title','location','country','experience_min','experience_max','salary_min','salary_max','education','vacancies','skills'] as $n)<label>{{ucwords(str_replace('_',' ',$n))}}<input name="{{$n}}" value="{{old($n,$n==='skills'?(is_array($job->requirements)?implode(', ',$job->requirements):''):($job->{$n}??($n==='country'?'India':($n==='vacancies'?1:''))))}}"></label>@endforeach<label>Employment type<select name="job_type"><option>Full Time</option><option>Part Time</option><option>Contract</option><option>Internship</option><option>Temporary</option></select></label><label>Work mode<select name="work_mode"><option>Office</option><option>Hybrid</option><option>Remote</option></select></label><label>Description<textarea name="description">{{old('description',$job->description)}}</textarea></label><label><input type="checkbox" name="is_confidential" value="1"> Confidential employer</label><style>label{display:block;margin:10px 0}input,select,textarea{display:block;width:100%;box-sizing:border-box;padding:11px}textarea{min-height:170px}</style><button name="action" value="draft">Save draft</button> <button name="action" value="submit">Submit for validation</button></form></body></html>
